package com.codepathacademy.learning;
import jakarta.validation.Valid;import java.util.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/progress") public class ProgressController {private final ProgressService progress;public ProgressController(ProgressService progress){this.progress=progress;}@GetMapping("/overview") ProgressService.Overview overview(@AuthenticationPrincipal String userId){return progress.overview(userId);}@GetMapping("/classes/{id}") ProgressService.View clazz(@AuthenticationPrincipal String userId,@PathVariable UUID id){return progress.classProgress(userId,id);}@PutMapping("/classes/{id}") ProgressService.View clazz(@AuthenticationPrincipal String userId,@PathVariable UUID id,@Valid @RequestBody Request request){return progress.setClass(userId,id,request.state(),request.version());}@GetMapping("/topics/{id}") ProgressService.View topic(@AuthenticationPrincipal String userId,@PathVariable UUID id){return progress.topicProgress(userId,id);}@PutMapping("/topics/{id}") ProgressService.View topic(@AuthenticationPrincipal String userId,@PathVariable UUID id,@Valid @RequestBody Request request){return progress.setTopic(userId,id,request.state(),request.version());}public record Request(ProgressState state,long version){}}
